#!/bin/sh
# Usage: roots.sh <out.txt>   tracked + untracked ts/tsx files of the lowering scope (repo-relative, one per line)
cd /Users/ueli/Documents/semio || exit 2
OS="🧰️framework/🛍️products/💻️os"; M="$OS/🔨️modules"; FM="🧰️framework/🔨️modules"
P=":(glob)$OS/🟦️.ts :(glob)$OS/🧪️tests/**/*.ts :(glob)$OS/🎚️config/**/*.ts :(glob)$M/📇️directory/**/*.ts :(glob)$M/📇️directory/**/*.tsx :(glob)$M/🧵️backbone/**/*.ts :(glob)$M/📞️directory-client/**/*.ts :(glob)$M/💡️inference/**/*.ts :(glob)$M/🌉️mcp/🧵️bridge/**/*.ts :(glob)$M/🌉️mcp/🐚️channel/**/*.ts :(glob)$M/🖥️shell/**/*.ts :(glob)$M/🏪️store/👷️worker/**/*.ts :(glob)$M/🔌️plugin/🌐️browser-bundle/**/*.ts :(glob)$M/🔌️plugin/📇️registry/**/*.ts :(glob)$M/🔌️plugin/📡️backbone/**/*.ts :(glob)$M/🔌️plugin/📥️receipt/**/*.ts :(glob)$M/🔌️plugin/📦️model/**/*.ts :(glob)$M/🔌️plugin/🖨️describe/🏷️component-receipt/**/*.ts :(glob)$M/📺️renderer/🧑‍🎨engine/🎯️targets/⚛️react/**/*.ts :(glob)$M/📺️renderer/🧑‍🎨engine/🎯️targets/⚛️react/**/*.tsx :(glob)$M/📺️renderer/🧑‍🎨engine/🧱️elements/**/*.ts :(glob)$M/📺️renderer/🧑‍🎨engine/🧱️elements/**/*.tsx :(glob)$M/📺️renderer/🧑‍🎨engine/🎚️UiPreferences/**/*.ts :(glob)$M/📺️renderer/🧑‍🎨engine/💾️resident/**/*.ts :(glob)$M/📺️renderer/🧑‍🎨engine/🧵️work/**/*.ts :(glob)$M/📺️renderer/🧑‍🎨engine/🎯️targets/🧊️wgpu/**/*.ts :(glob)$FM/📄️document/**/*.ts :(glob)$FM/💡️inference/**/*.ts :(glob)$FM/🎁️packs/**/*.ts :(glob)$FM/🖼️assets/**/*.ts :(glob)$FM/🌐️browser-bundle/**/*.ts :(glob)$FM/📇️directory/**/*.ts :(glob)$FM/📇️directory/**/*.tsx :(glob)$FM/🛰️backbone/**/*.ts :(glob)$FM/📞️directory-client/**/*.ts :(glob)🌎️hub/**/*.ts :(glob)🏢️semio-tech/🎡️play/**/*.ts"
{ git -c core.quotepath=false -c core.fsmonitor=false ls-files -- $P; git -c core.quotepath=false -c core.fsmonitor=false ls-files --others --exclude-standard -- $P; } | /usr/bin/grep -v "node_modules\|/🤖️generated/\|/🕸️bindings/" | sort -u > "$1"
wc -l < "$1"
